type Password = {
  value: Str;
  invariant: string.str_len(value) >= 8;
}

fn Password.strength(self: &Self) -> Int {
  let score = 0;
  if string.str_len(self.value) >= 12 { score = score + 1; }
  score = score + 1;
  return score;
}

fn Password.mask(self: &Self) -> Str {
  let masked = "";
  var i = 0;
  while i < string.str_len(self.value) {
    masked = masked + "*";
    i = i + 1;
  }
  return masked;
}

fn main() -> Int {
  let pw: Password = Password{ value: "Str0ngP@ss!" };
  io.println("Strength: " + pw.strength());
  io.println("Masked: " + pw.mask());
  return 0;
}
